from solution import get_total_number_of_sequences


def test_issue_example_10_4():
    """Example get_total_number_of_sequences(10, 4) == 4."""
    assert get_total_number_of_sequences(10, 4) == 4  # 3 (a3=4 -> 8,9,10) + 1 (a3=5 -> 10) = 4


def test_issue_single_length_equals_m():
    """Length-1 sequences need only element less than or equal to m."""
    assert get_total_number_of_sequences(10, 1) == 10  # values 1..10 = 10


def test_issue_two_length_small_m():
    """Each next element is greater than or equal to twice of the previous element."""
    assert get_total_number_of_sequences(4, 2) == 4  # (4-2+1)=3 + (4-4+1)=1 => 3+1=4


def test_issue_two_length_large_m():
    """Each next element is greater than or equal to twice of the previous and <= m."""
    assert get_total_number_of_sequences(10, 2) == 25  # 9+7+5+3+1=25


def test_issue_three_length_small_m():
    """Sequences of length n such that each next is >= twice previous and <= m."""
    assert get_total_number_of_sequences(5, 3) == 2  # [1,2,4] + [1,2,5] => 1+1=2


def test_issue_three_length_large_m():
    """Sequences of length n such that each next is >= twice previous and <= m."""
    assert get_total_number_of_sequences(10, 3) == 20  # (7+5+3+1)=16 + (3+1)=4 => 16+4=20


def test_issue_exact_power_of_two_fit():
    """Exact fit chain [1,2,4,8] is counted when m equals the minimum maximum."""
    assert get_total_number_of_sequences(8, 4) == 1  # only [1,2,4,8] => 0+1=1


def test_issue_just_below_minimum_fit():
    """No sequence fits when m is just below the minimal doubling chain."""
    assert get_total_number_of_sequences(7, 4) == 0  # minimal end 1*2*2*2=8 > 7 => 0


def test_issue_just_above_minimum_fit():
    """Two sequences fit when m is just above the minimal doubling chain."""
    assert get_total_number_of_sequences(9, 4) == 2  # [1,2,4,8] + [1,2,4,9] => 1+1=2


def test_issue_impossible_pair_small_m():
    """No length-2 sequence fits when m is too small for doubling."""
    assert get_total_number_of_sequences(1, 2) == 0  # need a2>=2*1=2 > 1 => 0


def test_contract_returns_int():
    """The number of possible sequences is an integer count."""
    result = get_total_number_of_sequences(10, 4)
    assert isinstance(result, int)  # counts are ints


def test_contract_keyword_m_n():
    """Public interface is get_total_number_of_sequences(m, n)."""
    assert get_total_number_of_sequences(m=10, n=4) == 4  # 3+1=4
